/* ===== Layer 4 rev 4 mock-up · Portfolio (six owner-approved tabs), Sites directory, Financials root, pilot request ===== */
const PTABS = [['Overview','portfolio'],['Outcomes by site','portfolio/outcomes-by-site'],['Demand and capacity','portfolio/demand-and-capacity'],['Act first','portfolio/act-first'],['What changed','portfolio/what-changed'],['Scope & coverage','portfolio/scope']];
const ptabs = s => tabRow(PTABS,s.ptab||s.id);
const sec = (title,body,sub='',right='',id='') => `<section class="panel"${id?` id="${id}"`:''}><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>${body}</section>`;
const region = (label,html) => `<div class="table-wrap scroll-region" tabindex="0" role="region" aria-label="${escapeHtml(label)}">${html}</div>`;
const siteLink = sk => link(`site/${sk}`,SK[sk].name,'strong');

/* ---------- factor table (outcome → factors → leaves; target against October at every factor) ---------- */
const BOUND = {off:['Outside its limit','red'],at:['At its limit','amber'],near:['Near its limit','amber'],ok:['Within its limit','green']};
function devText(n){if(n.obs)return '<span class="muted">observed</span>';
 if(n.plan!=null&&n.actual!=null&&typeof n.plan==='number'){const d=r2(n.actual-n.plan);if(Math.abs(d)<0.005)return 'on plan';return (d>0?'+':'−')+fmtU(Math.abs(d),n.unit);}
 if(n.dev!=null)return (n.dev>0?'+':'−')+fmtU(Math.abs(n.dev),n.unit);return '—';}
function factorTable(sk,opts={}){const rows=[];
 walk(tree(sk),(n,d)=>{if(opts.depth!=null&&d>opts.depth)return;
  const lab=`<div class="fac" style="--d:${d}">${d?'<span class="fac-branch" aria-hidden="true">└</span>':''}<div><b>${n.label}</b>${n.residual?` <span class="badge outline">${n.resLabel||'not explained by the model yet'}</span>`:''}<small>${n.how}</small>${n.bound?`<small class="bnd">${badge(...BOUND[n.bound.state])} ${n.bound.text}</small>`:''}</div></div>`;
  const pl=n.plan!=null?fmtU(n.plan,n.unit):'<span class="muted">not declared</span>';
  const ac=n.actual!=null?fig(`node:${sk}:${n.id}`,fmtU(n.actual,n.unit)):'—';
  rows.push(`<tr class="${n.residual?'resid':''} ${d===0?'root':''}" data-node="${n.id}" data-key="${n.hkey||''}" data-home="${n.home||''}" data-via="${n.hvia||''}" data-actual="${typeof n.actual==='number'?n.actual:''}" data-heading="${n.lens||''}"><th scope="row">${lab}</th><td>${n.obs&&n.plan==null?'<span class="muted">—</span>':pl}</td><td>${ac}</td><td>${devText(n)}</td><td>${n.eff!=null&&!n.obs?(n.evd&&n.actual==null?fig(n.evd,usd(n.eff,true)):usd(n.eff,true)):'—'}</td><td>${ec(n.cls)}</td><td>${n.lens?lensTag(n.lens)+(n.potential?' <small class="cellnote">potential, beside Grow, not its actual</small>':''):''}</td><td>${n.dec?link(`decision/${n.dec}`,'Decision →'):''}</td></tr>`);});
 const cost=OPS[SK[sk].op].kind==='cost';
 return region(`Factor structure for ${SK[sk].name}`,`<table class="ftab"><thead><tr><th>Factor and how it composes</th><th>Target</th><th>October</th><th>Deviation</th><th>Effect on ${cost?'cost (+ lower)':'contribution'}</th><th>Evidence</th><th>Outcome</th><th></th></tr></thead><tbody>${rows.join('')}</tbody></table>`);}

/* ---------- value chain strip (stages with leaks between them) ---------- */
function chainStrip(op,sk){const o=OPS[op];let st;
 if(o.vertical==='mini'){const C=sk?{...siteM(sk).period.actual,plan_billed_kwh:siteM(sk).period.plan.billed_kwh,plan_revenue:siteM(sk).period.plan.revenue}:o.t.portfolio.chain;
  const loss=sk?(C.technical_loss_kwh??C.expected_technical_loss_kwh)+(C.unexplained_kwh||0):C.delivered_kwh-C.metered_kwh,unb=sk?(C.adjustments_kwh+(C.unbilled_mapping_kwh||0)):C.metered_kwh-C.billed_kwh;
  st=[['Usable capacity','Not available yet','needs the energy management export by time window','na'],['leak','idle capacity: not available yet'],['Delivered',num(C.delivered_kwh)+' kWh','Measured'],['leak',`losses ${num(loss)} kWh`],['Metered',num(C.metered_kwh)+' kWh','Measured'],['leak',`adjustments and unmapped meters ${num(unb)} kWh`],
   ['Billed',num(C.billed_kwh)+' kWh',`target ${num(C.plan_billed_kwh)} · Emulated`],['leak',''],['Revenue',usd(C.revenue),`target ${usd(C.plan_revenue)} · Emulated`],['leak',`in transit ${usd(C.in_transit)} · outstanding ${usd(C.outstanding)}`],['Cash collected',usd(C.collected),'Recorded']];}
 else if(o.vertical==='cold'){const t=o.t,C=sk?{capacity_crate_days:CAPCD(sk),occupied_crate_days:siteM(sk).period.actual.crate_days,plan_crate_days:siteM(sk).period.plan.crate_days,revenue:siteM(sk).period.actual.revenue,plan_revenue:siteM(sk).period.plan.revenue,collected:siteM(sk).period.actual.collected,outstanding:siteM(sk).period.actual.outstanding}:t.portfolio.chain;
  st=[['Capacity',num(C.capacity_crate_days)+' crate-days','Recorded'],['leak',`idle ${num(C.capacity_crate_days-C.occupied_crate_days)} crate-days`],['Occupied',num(C.occupied_crate_days)+' crate-days',`target ${num(C.plan_crate_days)} · Emulated`],['leak','no incompatible or off-rate-card occupancy recorded'],['Chargeable',num(C.revenue/t.prices.storage_usd_per_crate_day)+' crate-days','Calculated from records (ledger to invoice reconciliation)'],['leak','no ledger-to-invoice difference in October'],['Invoiced',usd(C.revenue),`target ${usd(C.plan_revenue)} · Emulated`],['leak',`outstanding ${usd(C.outstanding)}`],['Received',usd(C.collected),'Recorded']];}
 else {const C=sk?{delivered_kwh:siteM(sk).period.actual.kwh,departures_required:siteM(sk).period.actual.departures_required,departures_met:siteM(sk).period.actual.departures_met}:o.t.portfolio.chain;const dl=sk==='ruiru'?[`${num(NV('ruiru','actual','deliverable_kwh_night'))} kWh a night`,`from the depot structure, at the ${siteM('ruiru').physical.import_limit_kw} kW import limit`]:sk==='kasarani'?[`${num(KN().deliverable_kwh_night)} of ${num(KN().required_kwh_night)} kWh a night`,'since 1 Nov, calculated from records; full in October']:['Not available yet','needs the depot charging model per night'];
  st=[['Deliverable energy',dl[0],dl[1],sk?'':'na'],['leak',''],['Delivered',num(C.delivered_kwh)+' kWh','Measured'],['leak',''],['Required departures',num(C.departures_required),'Emulated (roster)'],['leak',`missed in October: ${num(C.departures_required-C.departures_met)}`],['Departures met',num(C.departures_met),'Recorded'],['leak',''],['Revenue','Not applicable','charging is a cost centre','na']];}
 const html=st.map(x=>x[0]==='leak'?`<li class="leak" aria-label="Leak: ${escapeHtml(x[1]||'none recorded')}"><span>${x[1]||'—'}</span></li>`:`<li class="stage ${x[3]==='na'?'na':''}"><small>${x[0]}</small><b>${x[1]}</b><span>${x[2]}</span></li>`).join('');
 return `<figure class="chainfig"><figcaption><strong>${sk?SK[sk].name:o.name} value chain, October</strong> · stages are factors; the gaps between them are leaks</figcaption><ol class="chain">${html}</ol></figure>`;}

/* ---------- Overview ---------- */
function headline(op){const o=OPS[op],T=opTotals(op),P=o.t.portfolio,res=residualOf(op);
 if(o.kind==='cost')return `October charging and depot cost, composed from the depots’ factors: ${usd(T.actual)} against a target of ${usd(T.plan)}, ${usd(-T.variance)} over. All ${num(P.departures_met)} required departures were met, at ${usd2(P.cost_per_departure_actual)} each (target ${usd2(r2(T.plan/P.departures_required))}).`;
 const G=gapByHeading(op);return `October contribution, composed from the sites’ factors: ${usd(T.actual)} against a target of ${usd(T.plan)}, ${usd(-T.variance)} short. By heading: Grow ${usd2s(G.grow)}, Optimize ${usd2s(G.optimize)}.`;}
function heroFigs(op){const o=OPS[op],T=opTotals(op),P=o.t.portfolio,A=P.allocation,res=residualOf(op),cv=P.coverage,M=o.t.portfolio_constraints,crew=derivedPlan(op).crew_visits_limit,used=derivedPlan(op).crew_visits_used;
 const plan=planCase(op);
 const h=(lab,val,note,cls)=>`<div class="hero"><span>${lab}</span><div class="herov">${val}</div><small>${note}</small>${cls?ec(cls):''}</div>`;
 const val=op==='lakeside'?plan.value:op==='harvest'?harvestValue():(derivedPlan('metro').value);
 const m12=h('Modelled 12-month change from the valued options',fig(`port:${op}:m12`,val===0?'$0':usd(val,true)),op==='harvest'?'Valued options only; includes an assumed recovery share (80%) at Kirinyaga':'Valued options only; includes design values not yet run on site data','MODELLED');
 return `<div class="heroes">${h(o.kind==='cost'?'Charging and depot cost':'Contribution',fig(`port:${op}:actual`,usd(T.actual)),`target ${usd(T.plan)} · ${fig(`port:${op}:cov`,pct(cv.cost_recorded_share,1))} of cost on emulated records`,'RECORDED')}
 ${(()=>{const G=gapByHeading(op);return h('Gap against target, by heading',fig(`port:${op}:variance`,usd(T.variance,true)),o.kind==='cost'?`Optimize ${usd2s(G.optimize)}, of which ${usd2s(G.residual)} not attributed yet (a target stated only as a bill total)`:`Grow ${usd2s(G.grow)} · Optimize ${usd2s(G.optimize)} · residual ${usd2s(G.residual)}`,'');})()}
 ${h('Plan spend',fig(`port:${op}:spend`,usd(plan.spend))+` <small>of ${usd(op==='lakeside'?LS.budget:M.budget_usd_nov_dec)}</small>`,`${num(plan.visits)} of ${num(derivedPlan(op).crew_visits_limit)} ${o.crewWord}`,'QUOTE')}
 ${m12}</div>`;}
/* R9-M4: every figure below is read from the evaluated nodes (DERIVED via applyDerived), bridge rows or manifest fields; none is typed. */
const NV=(sk,side,node)=>DSITE(sk)?.[side]?.nodes?.[node];
const BR=(sk,drv)=>(siteM(sk).period.bridge||[]).find(b=>b.driver===drv);
const BQ=(sk,drv)=>{const b=BR(sk,drv);return b?qtyOf(b.basis):null;};
const sgnK=v=>(v>0?'+':v<0?'−':'')+num(Math.abs(v));
const perCD=sk=>siteM(sk).period.actual.energy/siteM(sk).period.actual.crate_days;
const overPct=sk=>{const a=siteM(sk).period.actual;return (a.kwh-a.kwh_model)/a.kwh_model*100;};
const sumNodes=(op,side,node)=>OPS[op].sites.reduce((a,sk)=>a+(NV(sk,side,node)||0),0);
/* Rev 16.9/16.10 (OD-21): the four cards read the structure nodes whose home category they are (categoryCard below). CARDS holds only
   each card's position line and the context lines that are not a factor effect: ctx are realised, pot are potential (shown beside
   Grow, never as its actual). Every value is read from the evaluated nodes, bridge rows or the data; none is typed. */
const CARDS = {
 lakeside:()=>{const hu=OPT['MTO-HULLER'],ma=siteM('mto').period.actual;
  return {
  grow:{pos:`Revenue ${usd(sumNodes('lakeside','actual','revenue'))} against ${usd(sumNodes('lakeside','plan','revenue'))}`,ctx:[[`Billed kWh ${num(sumNodes('lakeside','actual','billed_kwh'))} against ${num(sumNodes('lakeside','plan','billed_kwh'))}`,'RECORDED']]},
  optimize:{pos:`Cost to serve ${usd(sumNodes('lakeside','actual','cost_to_serve'))} against ${usd(sumNodes('lakeside','plan','cost_to_serve'))}`,ctx:[[`Diesel litres ${num(sumNodes('lakeside','actual','diesel_l'))} against ${num(sumNodes('lakeside','plan','diesel_l'))}`,'RECORDED'],[`Mto: ${num(ma.unexplained_kwh)} kWh delivered beyond the expected losses and not metered; not priced, being investigated`,'DERIVED']]},
  protect:{},
  assure:{pos:`${pct(OPS.lakeside.t.portfolio.coverage.cost_recorded_share,1)} of cost on emulated records`,ctx:[['Kisiwa’s October maintenance-contract invoice missing: carried at target','ESTIMATED']]}};},
 harvest:()=>{const t=OPS.harvest.t,capc=CAPCD_ALL()/3,mw=siteM('mwea').period,ag=OPT['MWEA-AGG'],occ=sumNodes('harvest','actual','revenue')/t.prices.storage_usd_per_crate_day,pocc=sumNodes('harvest','plan','revenue')/t.prices.storage_usd_per_crate_day;
  return {
  grow:{pos:`Revenue ${usd(sumNodes('harvest','actual','revenue'))} against ${usd(sumNodes('harvest','plan','revenue'))}`,ctx:[[`Occupied crate-days ${num(occ)} against ${num(pocc)}: all at Mwea (${mw.actual.occupancy_pct}% full against ${mw.plan.occupancy_pct}%)`,'RECORDED']]},
  optimize:{pos:`Cost to serve ${usd(sumNodes('harvest','actual','cost_to_serve'))} against ${usd(sumNodes('harvest','plan','cost_to_serve'))}`,ctx:[[`Mwea within ${overPct('mwea').toFixed(1)}% of its model: high cost per crate-day is low occupancy`,'DERIVED'],[`Electricity per crate-day: Mwea $${perCD('mwea').toFixed(4)}, Kirinyaga $${perCD('kirinyaga').toFixed(4)}`,'DERIVED']]},
  protect:{},
  assure:{pos:`${pct(t.portfolio.coverage.cost_recorded_share,1)} of cost on emulated records`,ctx:[['Thika’s October service invoice missing: carried at target','ESTIMATED'],['Every October deviation attributed to an observed factor: nothing unexplained','DERIVED']]}};},
 metro:()=>{const P=OPS.metro.t.portfolio,a6=DOPT('RUI-ABSORB6'),ru=siteM('ruiru');
  const cost=sumNodes('metro','actual','cost_to_serve'),dep=sumNodes('metro','actual','departures_met'),planCost=opTotals('metro').plan;
  return {
  grow:{pos:'Revenue: not applicable · charging is a cost centre; Grow is service growth on the depots’ existing chargers',ctx:[]},
  optimize:{pos:`Cost ${usd(cost)} against ${usd(planCost)} · ${usd2(cost/dep)} a departure`,ctx:[]},
  protect:{},
  assure:{pos:`${pct(P.coverage.cost_recorded_share,1)} of cost on emulated records`,ctx:[['Kasarani’s October maintenance invoice missing: carried at target','ESTIMATED'],['Embakasi’s new tariff is an assumption until the invoice confirms it','CONTRACT']]}};}};
/* potential beside Grow, never Grow's actual (design §2.0): the data's list (MANIFEST.home_categories.potential) names each one;
   a line is written here only for a named entry, and an entry with no line is listed in POT_GAPS */
const POT_LINE={
 headroom:(op,p)=>[`Headroom with no customer: ${p.shown||'not available yet'}`,'MISSING'],
 letter_of_intent_demand:()=>{const hu=OPT['MTO-HULLER'];return [`Mto cooperative’s signed letter of intent: ${num(hu.load.kwh_month)} kWh a month of daytime demand, revenue only once it is connected`,'MODELLED'];},
 idle_capacity:op=>[`Idle capacity ${num(sumNodes(op,'actual','capacity_crate_days')-sumNodes(op,'actual','occupied_total_crate_days'))} crate-days: capacity with no customer yet`,'DERIVED'],
 spare_deliverable_energy:()=>{const a6=DOPT('RUI-ABSORB6'),ru=siteM('ruiru');return [`Ruiru can serve ${num(a6.params.added_buses)} more buses on its chargers: ${num(a6.bound.required_kwh_night)} of ${num(a6.bound.deliverable_kwh_night)} kWh a night; ${pct(ru.period.actual.charger_hour_utilisation)} of nameplate charger-hours and ${ruiruDeliverable()} of deliverable energy used (the ${ru.physical.import_limit_kw} kW import limit binds)`,'MODELLED'];}};
const POT_GAPS=[];window.POT_GAPS=POT_GAPS;
function potLines(op){return (HC.potential[VKEY[OPS[op].vertical]]||[]).map(p=>{const f=POT_LINE[p.name];if(!f){if(!POT_GAPS.includes(p.name))POT_GAPS.push(p.name);return null;}return f(op,p);}).filter(Boolean);}
/* money a service failure has already cost (design rev 16.11 §2.0, register call 17): a cost line under Optimize, already inside
   the bridge on its own factor, so listed here without an effect and never added again; its Protect side is named, in its own unit */
function serviceCostLines(op){const o=OPS[op],L=o.t.portfolio.service_cost_lines||[];
 return L.map(l=>{const nov=l.november_to_date?Object.entries(l.november_to_date).filter(([,v])=>typeof v==='number'):[],ps=l.protect_measure?PNAME[l.protect_measure]||l.protect_measure:null;
  const row=homeRow(o.vertical,l.node);
  return `<li data-service-cost="${l.id}" data-heading="${row?row[0]:''}"><span>${SCL_NAME[l.id]||cap(l.id)}: ${usd(l.portfolio)} in October${nov.length?`; ${nov.map(([k,v])=>`${usd(v)} at ${SK[siteKeyOf(op,k)]?.name||k}`).join(', ')} in November to ${fdate(AS_OF)}`:''} (target ${usd(l.target)})${ps?`. Its Protect side, in its own unit: ${ps.replace(/^./,c=>c.toLowerCase())}`:''}</span>${ec(l.class)}</li>`;});}
const SCL_NAME={customer_liability:'Customer compensation',qa_confirmed_damage_liability:'Customer compensation for damage confirmed by inspection',service_penalties:'Penalties for missed departures'};
/* ---------- the four headings over the structure (design §2.0, Figure 1b; §2.8 Overview cards) ----------
   Money effects: the bridge rows and the explicit residual, each on one leaf, so under one heading. Grow + Optimize = the
   contribution gap per Site (checked against the evaluated contribution, actual − target). Protect and Assure carry no money;
   the four headings are never added together. */
const isEffect=n=>n.eff!=null&&!n.obs&&Math.abs(n.eff)>0.004&&!n.kids&&((n.evd||'').startsWith('bridge:')||n.residual);
function effectsOf(sk){const out=[];walk(tree(sk),n=>{if(isEffect(n))out.push(n);});return out;}
function contribGap(sk){const a=NV(sk,'actual','contribution'),p=NV(sk,'plan','contribution'),st=DSITE(sk)?.plan?.stated_total;
 if(a==null)return null;if(p!=null)return r2(a-p);if(st!=null&&OPS[SK[sk].op].kind==='cost')return r2(a+st);return null;}
function siteSplit(sk){const s={grow:0,optimize:0,unplaced:0};effectsOf(sk).forEach(n=>{if(n.lens==='grow'||n.lens==='optimize')s[n.lens]+=n.eff;else s.unplaced+=n.eff;});
 return {grow:r2(s.grow),optimize:r2(s.optimize),unplaced:r2(s.unplaced),gap:contribGap(sk)};}
/* the overview's one split of the gap, by heading (spec §10; design §2.0, §2.2; review H M9): Grow, then Optimize, which add to
   the gap; each line is a factor's money effect read from the bridge rows and evaluated nodes (effectsOf), grouped by the factor's
   registry key; a residual line only where a leaf is unobserved (the registry's residual row, Ruiru's stated total). Nothing typed. */
const usd2s=n=>{const v=r2(n||0),a=Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});return (v<-0.0001?'−':v>0.0001?'+':'')+'$'+a;};
const GAP_WORD={billed_kwh:'kWh sold (demand volume)',metered_kwh:'kWh sold (demand volume)',candidate_l:'Candidate running',necessary_l:'Necessary running',unexplained_l:'Fuel the generator model does not explain',unmapped_kwh:'Meters not yet mapped to a customer',adjustments_kwh:'Authorised adjustments'};
function gapByHeading(op){const o=OPS[op],rows=[],G={grow:0,optimize:0,residual:0,gap:0,sites:{}};
 o.sites.forEach(sk=>{const g=contribGap(sk);G.sites[sk]=g;G.gap+=g||0;effectsOf(sk).forEach(n=>{if(n.lens!=='grow'&&n.lens!=='optimize')return;
  const word=n.residual?n.label:(GAP_WORD[n.hkey]||n.label),key=n.lens+'|'+word;let r=rows.find(x=>x.key===key);
  if(!r){r={key,lens:n.lens,word,hkeys:[],by:{},total:0,residual:!!n.residual};rows.push(r);}
  if(n.hkey&&!r.hkeys.includes(n.hkey))r.hkeys.push(n.hkey);r.by[sk]=r2((r.by[sk]||0)+n.eff);r.total=r2(r.total+n.eff);G[n.lens]+=n.eff;if(n.residual)G.residual+=n.eff;});});
 const ord=Object.values(GAP_WORD);rows.sort((a,b)=>(a.lens===b.lens?0:a.lens==='grow'?-1:1)||((ord.indexOf(a.word)+1||99)-(ord.indexOf(b.word)+1||99))||Math.abs(b.total)-Math.abs(a.total));
 return {...G,grow:r2(G.grow),optimize:r2(G.optimize),residual:r2(G.residual),gap:r2(G.gap),rows};}
function gapSplit(op){const o=OPS[op],G=gapByHeading(op),cost=o.kind==='cost',T=opTotals(op),c=v=>v==null?'<span class="muted">—</span>':usd2s(v);
 const siteCells=r=>o.sites.map(sk=>`<td data-site="${sk}" data-v="${r.by[sk]??''}">${r.by[sk]==null?'<span class="muted">—</span>':usd2s(r.by[sk])}</td>`).join('');
 const body=['grow','optimize'].map(k=>{const R=G.rows.filter(r=>r.lens===k);if(k==='grow'&&cost)return `<tr data-split-heading="grow" data-split-total="0"><th scope="row">${lensTag('grow')}</th><td colspan="${o.sites.length+2}"><span class="muted">Not applicable: charging is a cost centre</span></td></tr>`;
  const tot=r2(R.reduce((a,r)=>a+r.total,0));
  return R.map(r=>`<tr data-split-heading="${k}" data-split-key="${r.hkeys.join(',')}" data-split-total="${r.total}"${r.residual?' class="resid"':''}><th scope="row">${lensTag(k)}</th><td>${r.word}</td>${siteCells(r)}<td><b>${usd2s(r.total)}</b></td></tr>`).join('')
   +`<tr class="subtotal" data-split-heading="${k}" data-split-subtotal="${tot}"><th scope="row">${lensTag(k)}</th><td><b>Total</b></td>${o.sites.map(sk=>`<td>${usd2s(R.reduce((a,r)=>a+(r.by[sk]||0),0))}</td>`).join('')}<td><b>${usd2s(tot)}</b></td></tr>`;}).join('');
 const foot=`<tr class="root" data-split-gap="${G.gap}" data-split-residual="${G.residual}"><th scope="row" colspan="2">${cost?'Cost against target':'Contribution gap'}, actual ${usd(T.actual)} against target ${usd(T.plan)}</th>${o.sites.map(sk=>`<td>${c(G.sites[sk])}</td>`).join('')}<td><b>${usd2s(G.gap)}</b>, residual ${usd2s(G.residual)}</td></tr>`;
 return sec('The gap, split by heading',region('The gap, split by heading',`<table class="ftab gapsplit"><thead><tr><th>Heading</th><th>Factor</th>${o.sites.map(sk=>`<th>${SK[sk].name}</th>`).join('')}<th>${o.name}</th></tr></thead><tbody>${body}${foot}</tbody></table>`),
  cost?'One split only: every effect sits under Optimize, because revenue is not applicable at a captive depot. A residual appears only where a leaf is not observed: Ruiru’s target is a bill total.':'One split only, by heading: Grow then Optimize, which add to the gap. A residual appears only where a leaf is not observed; here it is zero.');}
/* a decision takes the heading of its Finding's factor, where the executive met the problem; with no Finding behind it, its lever's
   (design rev 16.12 §2.0, OD-25), read from the data's decision rows (MANIFEST.home_categories.decisions[].heading, which the
   manifest check holds to the Finding factor's and the lever's registry rows); a decision with no row has no heading and is listed in DEC_GAPS */
const DEC_GAPS=[];window.DEC_GAPS=DEC_GAPS;
function decHeading(id){const r=(HC.decisions||[]).find(x=>x.id===id);if(r&&LENS[r.heading])return r.heading;if(id&&!DEC_GAPS.includes(id))DEC_GAPS.push(id);return null;}
/* a Finding takes the heading of its own row (MANIFEST.home_categories.findings[], design rev 16.12 §2.0, OD-25): the registry row of the
   row's factor (homeRow), or Grow for a potential factor (an opportunity, beside Grow). A linked Finding (origin: false) takes its own
   heading, not its decision's. An attention row with no Finding id, or no registry row, is a gap, never guessed */
const FIND_GAPS=[];window.FIND_GAPS=FIND_GAPS;
function findingFactorHeading(fid,tag){const r=(HC.findings||[]).find(x=>x.id===fid),sk=r?Object.keys(SK).find(k=>SK[k].name===r.site.replace(/^Room [A-C] · /,'')):null,v=sk?OPS[SK[sk].op].vertical:null;
 const row=r&&v?homeRow(v,r.factor):null,pot=r&&v?(HC.potential[VKEY[v]]||[]).some(p=>p.name===r.factor):false;
 if(row&&LENS[row[0]])return row[0];if(pot)return 'grow';const g=fid||tag||'no id';if(!FIND_GAPS.includes(g))FIND_GAPS.push(g);return null;}
const findingHeading=([k,t,s,txt,d,fid])=>findingFactorHeading(fid,`${s}:${d}`);
/* each option's money lines under the headings of the money factors the data names for it (HC.option_money_factors, design
   rev 16.12 §2.0, OD-25: each effect under its own factor's heading, whatever the decision's heading; money counted once): with
   factors under both Grow and Optimize, revenue under Grow and its cost lines under Optimize; with factors under one heading, the
   option's evaluated change under that heading. Protect measures are shown in their own units, never money. A named factor with no
   registry row, or a split the figures cannot make, is listed in OPT_HOME_GAPS. The billed-charges fix is not a valued option and
   names no money factor: its billed charges are listed under Optimize (unmapped meters, O3), not summed. */
const OPT_HOME_GAPS=[];window.OPT_HOME_GAPS=OPT_HOME_GAPS;
const COST_LINES=['fuel_monthly','collection_cost_monthly','energy_monthly','handling_monthly'];
function optHeadings(id){const x=OPT[id];if(!x)return [];const e=x.economics||{},dd=DOPT(id),out=[],sk=x._site,v=sk?OPS[SK[sk].op].vertical:null;
 const F=(HC.option_money_factors||{})[id]||[],rows=F.map(f=>v?homeRow(v,f):null),hs=[...new Set(rows.filter(Boolean).map(r=>r[0]))];
 const gap=()=>{if(!OPT_HOME_GAPS.includes(id))OPT_HOME_GAPS.push(id);};
 if(F.length){if(rows.some(r=>!r)||hs.some(h=>h!=='grow'&&h!=='optimize'))gap();
  else if(hs.length===2){const c=COST_LINES.reduce((a,k)=>a+(e[k]||0),0);if(e.revenue_monthly!=null&&e.net_monthly!=null&&Math.abs(e.revenue_monthly-c-e.net_monthly)<0.005){out.push(['grow',`${usd(e.revenue_monthly,true)} a month`,e.revenue_monthly]);out.push(['optimize',`${usd(-c,true)} a month`,-c]);}else gap();}
  else if(hs.length===1&&e.charges_monthly!=null&&!(dd&&dd.valued_in_money))out.push([hs[0],`${usd(e.charges_monthly,true)} a month of restored charges, listed, not added`,e.charges_monthly]);
  else if(dd&&dd.valued_in_money&&dd.value!=null&&dd.monthly_or_horizon_change)out.push([hs[0],`${usd(dd.monthly_or_horizon_change,true)} ${dd.months>1?'a month':'to the restore'}`,dd.monthly_or_horizon_change]);}
 else if(e.charges_monthly!=null)out.push(['optimize',`${usd(e.charges_monthly,true)} a month of billed charges`,e.charges_monthly]);
 const pe=protectEffectLine(id);if(pe)out.push(['protect',cap(pe)+' (not money)',null]);
 return out;}
function byHeading(id){const h=optHeadings(id);return h.length?`<ul class="byhead">${h.map(([k,t])=>`<li data-heading="${k}">${lensTag(k)} <span>${t}</span></li>`).join('')}</ul>`:'<span class="muted">No effect under a heading yet</span>';}
const CAT_NOTE={grow:'Factor effects on contribution',optimize:'Factor effects on contribution',protect:'Measures against target'};
function evidenceMix(op){const c={};OPS[op].sites.forEach(sk=>walk(tree(sk),n=>{if(n.cls&&!n.kids){const w=ecw(n.cls);c[w]=(c[w]||0)+1;}}));return Object.entries(c).sort((a,b)=>b[1]-a[1]).map(([w,n])=>`${w} ${num(n)}`).join(' · ');}
/* collection of what was billed (design rev 16.10 §2.0, Optimize: billed against collected): cash, outside the contribution gap */
function cashLines(op){const o=OPS[op];if(o.vertical==='ev')return [];const w=o.vertical==='cold'?['received','invoiced']:['collected','billed'],ck=w[0]; /* the cash node: `received` at a cold room, `collected` on a mini-grid */
 const rows=o.sites.map(sk=>{const A=siteM(sk).period.actual,c=NV(sk,'actual',ck)??A.collected,b=NV(sk,'actual','revenue')??A.revenue,tr=NV(sk,'actual','in_transit')??A.in_transit,ou=NV(sk,'actual','outstanding')??A.outstanding;
  return `<li data-cash="${sk}" data-cash-value="${c}"><span>${SK[sk].name}: ${usd(c)} ${w[0]} of ${usd(b)} ${w[1]}${tr?`; ${usd(tr)} in transit`:''}; ${usd(ou)} outstanding</span>${ec('RECORDED')}</li>`;});
 const C=sumNodes(op,'actual',ck),B=sumNodes(op,'actual','revenue');
 return [...rows,`<li data-cash="portfolio" data-cash-value="${r2(C)}"><span>Across ${o.name}: ${usd(C)} ${w[0]} of ${usd(B)} ${w[1]}</span></li>`];}
/* contribution's bridge, presented under Assure (actual against target, with sources and coverage); every figure in it is a Grow or
   Optimize figure, tagged with its heading, so Assure adds no money of its own */
function bridgeTable(op){const o=OPS[op],cost=o.kind==='cost',rows=o.sites.map(sk=>[sk,siteSplit(sk)]),tot=rows.reduce((a,[,s])=>({grow:a.grow+s.grow,optimize:a.optimize+s.optimize,gap:a.gap+(s.gap||0)}),{grow:0,optimize:0,gap:0});
 const cell=v=>usd(r2(v),true),gw=v=>cost?'<span class="muted">Not applicable</span>':cell(v);
 const body=rows.map(([sk,s])=>`<tr data-site="${sk}" data-grow="${s.grow}" data-optimize="${s.optimize}" data-gap="${s.gap}"><th scope="row">${siteLink(sk)}</th><td>${gw(s.grow)}</td><td>${cell(s.optimize)}</td><td><b>${s.gap==null?'not available yet':fig(`node:${sk}:root`,cell(s.gap))}</b></td></tr>`).join('');
 return `<details class="cb-disc contrib-bridge"><summary>${cost?'Cost':'Contribution'}’s bridge by heading</summary>${region('Bridge by heading',`<table class="ftab cbtab"><thead><tr><th>Site</th><th>Grow</th><th>Optimize</th><th>${cost?'Cost against target':'Against target'}</th></tr></thead><tbody>${body}<tr class="root" data-site="portfolio"><th scope="row">All sites</th><td>${gw(tot.grow)}</td><td>${cell(tot.optimize)}</td><td><b>${cell(tot.gap)}</b></td></tr></tbody></table>`)}<p class="note">${cost?'Revenue is not applicable at a captive depot, so the whole gap sits under Optimize.':'Grow and Optimize effects add up to each gap.'} These are Grow and Optimize figures; Assure adds none.</p></details>`;}
/* Assure (design rev 16.10 §2.0): the governed, evidenced view of everything above, in five parts, with no money of its own */
function assureGroups(op,C){const o=OPS[op],li=([t,c])=>`<li><span>${t}</span>${c?ec(c):''}</li>`,decs=DEC.filter(d=>SK[d.site].op===op),opts=decs.flatMap(d=>d.opts.map(id=>OPT[id]).filter(Boolean));
 const rej=opts.filter(x=>x.disposition==='REJECTED').length,lim=opts.filter(x=>(x.safeguard||{}).result==='FAIL').length,acts=(WF(op).actions||[]).length;
 const rights=(RIGHTS_OF_OP[op]||[]).map(k=>{const r=rightsOf(k),i=STAGE_IX[r.state];return li([`${r.asset}: ${i>=0?STAGES[i].toLowerCase():'no claim possible'}${r.deadline?`; deadline ${fdate(r.deadline)}, ${daysUntil(r.deadline)} days`:''}${r.stopped?`; ${r.stopped}`:''}`.replace(/\$[\d,.]+/g,'').replace(/\s+;/g,';'),'']);});
 const verd=COMMIT[op].map(([d,what,,state])=>li([`${what.replace(/\$[\d,.]+/g,'')}: three verdicts not yet · ${state.replace(/\$[\d,.]+/g,'')}`,'']));
 return [['Actual against target, with sources and coverage',[li([C.assure.pos,'']),li([`Evidence by type, every factor: ${evidenceMix(op)}`,'']),`<li class="cb-li">${bridgeTable(op)}</li>`]],
  ['Options against doing nothing, with their limits',[li([`${num(decs.length)} decisions compare every option with doing nothing; ${num(rej)} option${rej===1?'':'s'} rejected, each with its reason${lim?`; ${num(lim)} fail${lim===1?'s':''} a limit`:''}`,''])]],
  ['Actions and the three verdicts',[li([`${num(acts)} Actions tracked, each with its owner`,'']),...verd]],
  ['Evidence the product keeps',[li(['Every figure keeps its source records, its evidence type and where it came from','']),...(C.assure.ctx||[]).map(li),
   ...(HOME_GAPS.some(g=>o.sites.includes(g.site))?[li([`Not yet under a heading: ${HOME_GAPS.filter(g=>o.sites.includes(g.site)).map(g=>`${SK[g.site].name}: ${g.label}`).join('; ')}`,'MISSING'])]:[])]],
  ['Contract notices and remedies',rights.length?rights:[li(['No right or contract notice open',''])]]];}
function categoryCard(op,k,C){const o=OPS[op],[name,ico]=LENS[k],P=planCase(op),li=([t,c])=>`<li><span>${t}</span>${c?ec(c):''}</li>`,grp=(h,rows)=>rows.length?`<h4>${h}</h4><ul>${rows.join('')}</ul>`:'';
 const head=`<article class="ocard lens-b-${k}" data-heading="${k}"><div class="ocard-h">${icon(ico)}<h3>${name}</h3></div>`;
 if(k==='assure')return `${head}<p class="ocard-pos">The evidence behind every heading; no money of its own</p>${assureGroups(op,C).map(([h,r])=>grp(h,r)).join('')}${link('portfolio/scope','Open Scope & coverage →')}</article>`;
 let pos=C[k].pos||'',facts=[],pot=k==='grow'?potLines(op).map(li):[];
 if(k==='grow'||k==='optimize'){o.sites.forEach(sk=>effectsOf(sk).filter(n=>n.lens===k).sort((a,b)=>Math.abs(b.eff)-Math.abs(a.eff)).forEach(n=>facts.push(`<li data-effect="${r2(n.eff)}" data-site="${sk}"><span>${SK[sk].name} · ${n.label}${n.residual&&!/not attributed/i.test(n.label)?' (not explained yet)':''}: <b>${usd(n.eff,true)}</b></span>${ec(n.cls)}</li>`)));
  facts.push(...(C[k].ctx||[]).map(li));if(k==='optimize')facts.push(...opsCardLines(op).map(li));}
 else {const pc=protectCard(op);pos=pc.pos;facts=pc.f.map(li);
  ATTN[op].filter(r=>r[0]==='unobs'&&findingHeading(r)==='optimize').forEach(([,,s,txt,d])=>facts.push(`<li class="linked" data-linked="${d}"><span>Possible fuel loss, linked and not counted here: ${SK[s].name} · ${txt}. Its cost sits under Optimize. ${link(`decision/${d}`,'Open the finding →')}</span></li>`));}
 const finds=ATTN[op].filter(r=>findingHeading(r)===k).map(([,t,s,txt,d])=>`<li><span><b>${t}</b> · ${SK[s].name}: ${txt} ${link(`decision/${d}`,'Decision →')}</span></li>`);
 const items=P.ids.map(id=>[id,optHeadings(id).find(h=>h[0]===k)]).filter(([,h])=>h).map(([id,h])=>`<li data-item="${id}"><span>${optLabel(id)} · ${SK[OPT[id]._site].name}: ${h[1]}</span></li>`);
 if(k==='protect')proactiveOf(op).forEach(it=>items.push(`<li data-item="${it.item}"><span>${it.label}: upkeep, no value claimed</span></li>`));
 const chosen=COMMIT[op].filter(([d])=>decHeading(d)===k);
 const verd=[`<li><span>${chosen.length?`${num(chosen.length)} chosen option${chosen.length===1?'':'s'} tracked; three verdicts not yet`:'No chosen option yet'}</span></li>`];
 return `${head}<p class="ocard-pos">${pos}</p>${grp(CAT_NOTE[k],facts)}${k==='optimize'?grp('Money a service failure has cost: a cost line, counted once',serviceCostLines(op))+grp('Cash collected, outside the contribution gap',cashLines(op)):''}${k==='grow'?grp('Potential, not realised',pot):''}${grp('Findings on these factors',finds)}${grp('Plan items that would move them',items)}${grp('Verdicts',verd)}${link('portfolio/outcomes-by-site','Open the factor structure →')}</article>`;}
function outcomeCards(op){const C=CARDS[op]();return `<div class="ocards">${Object.keys(LENS).map(k=>categoryCard(op,k,C)).join('')}</div><p class="note">The four headings sit over one structure: each factor under one heading, so no figure is counted twice and the headings are never added together. Grow and Optimize effects explain the contribution gap; cash collected sits under Optimize, outside that gap; Protect shows measures against target with values at stake listed beside, never money; Assure shows the evidence, with the bridge, and adds no money.</p>`;}
function ATTN_OF(op){const ko=siteM('kobo').period,cand=BR('kobo','CANDIDATE_RUNNING'),mto=siteM('mto'),kfb=ko.fuel_balance,mw=siteM('mwea').period,emb=siteM('embakasi'),ka=siteM('kasarani').incident,ru=siteM('ruiru');
 return {
 lakeside:[['off','Off target','kobo',`Litres used ${num(ko.actual.diesel_l)} against ${num(ko.plan.diesel_l)} target; ${num(qtyOf(cand.basis)[0])} L of it is candidate running while solar and the battery could carry the load`,'kobo-generator','kobo-candidate'],['at','At its limit','kisiwa','Evening supply on one generator at 95% load since generator 1 failed on 30 Oct','kisiwa-genset','kisiwa-one-generator'],['new','Opportunity','mto',`The cooperative’s signed letter of intent for a daytime rice huller; it lapses on ${fdate('2026-11-30')}`,'mto-demand','mto-letter-of-intent'],['due','Deadline','mto',`Inverter 2 failed on ${fdate(mto.entitlement.occurrence.failed)}: half the daytime capacity; warranty notice due ${fdate(mto.entitlement.notice_deadline)}`,'mto-inverter','mto-inverter-notice'],['off','Off target','mto',`${num(mto.period.actual.unbilled_mapping_kwh)} kWh metered but not billed after the 3 Oct meter swap`,'mto-billing','mto-unbilled'],['unobs','Not explained','kobo',`${num(kfb.residual_l)} L of fuel beyond what the generator model explains (above the ${kfb.tolerance_pct}% tolerance): investigation, no recovery claimed`,'kobo-generator','kobo-unexplained-fuel']],
 harvest:[['off','Off target','mwea',`Occupied crate-days ${num(NV('mwea','actual','revenue')/OPS.harvest.t.prices.storage_usd_per_crate_day)} against ${num(NV('mwea','plan','revenue')/OPS.harvest.t.prices.storage_usd_per_crate_day)} target (${mw.actual.occupancy_pct}% full against ${mw.plan.occupancy_pct}%)`,'mwea-occupancy','mwea-occupancy'],['off','Off target','kirinyaga',`Electricity ${Math.round(overPct('kirinyaga'))}% above what its occupancy explains (tolerance ${OPS.harvest.t.energy_model.tolerance_pct}%)`,'kirinyaga-energy','kirinyaga-excess'],['at','Limit breached','thika',`A batch was above its 5 °C limit for 20–30 minutes on 6 Oct after the backup failed to start; the controller is replaced on ${fdate(siteM('thika').entitlement.remedy_scheduled)}`,'thika-backup','thika-backup-start'],['new','Opportunity','mwea',`The aggregator’s draft contract: ${num(DOPT('MWEA-AGG').params.crates)} crates, December to March`,'mwea-occupancy','mwea-aggregator']],
 metro:[['off','Below its limit','kasarani',`On target in October. Since 1 Nov charger 2 is down: ${num(KN().deliverable_kwh_night)} of ${num(KN().required_kwh_night)} kWh a night, so departures are at risk; ${num(KN().departures_missed)} missed so far`,'kasarani-charger','kasarani-charger-down'],['off','Off target','embakasi',`${pct(emb.period.actual.peak_share)} of charging at peak price against ${pct(emb.period.plan.peak_share)} target`,'embakasi-schedule','embakasi-peak-share'],['at','At its limit','embakasi',`Monthly peak import ${emb.period.actual.max_kw} kW: at the ${emb.physical.import_limit_kw} kW limit`,'embakasi-schedule','embakasi-import-limit'],['new','New tariff','embakasi','From 1 Nov the tariff adds a 00:00–05:00 rate at $0.09','embakasi-schedule','embakasi-night-rate'],['new','Opportunity','ruiru','The city offers 6 more buses on a new route','ruiru-expansion','ruiru-route-offer'],['near','Near its limit','ruiru',`Peak import ${ru.period.actual.max_kw} kW of a ${ru.physical.import_limit_kw} kW limit`,'ruiru-expansion','ruiru-import-limit'],['low','Low','ruiru','Charger 7, connector 2 silent since 6 Oct; no departure depends on it','ruiru-connector','ruiru-connector-fault']]}[op];}
const ATTN=new Proxy({},{get:(_,op)=>ATTN_OF(op)});
function attentionList(op,sk){const rows=ATTN[op].filter(r=>!sk||r[2]===sk);if(!rows.length)return '<p class="note">No factor at this site is off target, at a limit or newly appeared.</p>';
 return `<ul class="attn">${rows.map(([k,t,s,txt,d])=>`<li class="attn-${k}"><span class="attn-k">${t}</span><div>${sk?'':`<b>${SK[s].name}</b> · `}${txt}</div>${link(`decision/${d}`,'Decision →')}</li>`).join('')}</ul>`;}
function CONTRAST_OF(op){const ks=siteM('kisiwa').period.actual,ko=siteM('kobo').period.actual,cand=BR('kobo','CANDIDATE_RUNNING'),st=OPT['KOB-STOPSOC'],mw=siteM('mwea').period,ki=siteM('kirinyaga').period.actual,ch=OPT['EMB-CHEAPEST'],dl=OPT['EMB-DEADLINE'];
 return {
 lakeside:[['Kisiwa burns the most diesel and has nothing to save.',`Kisiwa used ${num(ks.diesel_l)} L in October, the most in the portfolio, but every generator interval was needed: a rainy month and evening load larger than solar plus battery. Kobo used ${ko.diesel_l<=ks.diesel_l/2?'half as much':num(ko.diesel_l)+' L'}, yet ${num(qtyOf(cand.basis)[0])} L of its running was candidate running while solar could carry the load; of that, the best feasible option avoids ${num(st.forward_replay.avoidable_fuel_l)} L a month (Modelled), worth ${usd(st.economics.net_12m)} over 12 months.`,'kobo-generator','Kobo’s generator decision']],
 harvest:[['Mwea has the worst cost per crate-day and healthy equipment.',`Mwea’s electricity per crate-day ($${perCD('mwea').toFixed(4)}) is the highest, but it is within ${overPct('mwea').toFixed(1)}% of what its occupancy needs: it is ${mw.actual.occupancy_pct}% full against a ${mw.plan.occupancy_pct}% target, so the lever is a customer, not a compressor. Kirinyaga looks fine ($${perCD('kirinyaga').toFixed(4)}) but uses ${Math.round(overPct('kirinyaga'))}% more electricity than its ${ki.occupancy_pct}% occupancy explains: there the lever is a ${usd(OPT['KIRI-REPAIR'].cost)} repair.`,'mwea-occupancy','Mwea’s occupancy decision']],
 metro:[['An idle connector ranks below a busy depot’s fault, and the cheapest schedule is rejected.',`Ruiru’s charger 7, connector 2 has been silent since 6 Oct, but no departure depends on it. Kasarani was on target in October, yet since 1 Nov one bus is short of charge every night: that comes first. At Embakasi the cheapest bill (00:00–05:00 only, ${usd(ch.economics.energy_cost_monthly)} a month) leaves ${ch.buses_short} buses short every night, so the departure-time schedule (${usd(dl.economics.energy_cost_monthly)}) wins.`,'kasarani-charger','Kasarani’s charger decision']]}[op];}
const CONTRAST=new Proxy({},{get:(_,op)=>CONTRAST_OF(op)});
function contrastPanel(op){return sec('Sites that look alike need different levers',CONTRAST[op].map(([h,p,d,l])=>`<article class="contrast"><h3>${h}</h3><p>${p}</p>${link(`decision/${d}`,`Open ${l} →`)}</article>`).join(''));}
function firstMoves(op){const P=planCase(op);return `<section class="moves-strip" aria-labelledby="fm-h"><h2 id="fm-h">The plan’s first three moves</h2><ol>${P.rows.slice(0,3).map(r=>`<li>${link(`decision/${DEC_SEE_ALSO[r.id]||decOf(r.id).id}`,optLabel(r.id))} <small>${SK[OPT[r.id]._site].name}</small></li>`).join('')}</ol>${link('portfolio/act-first','Open the plan →')}</section>`;}
function overviewScreen(){const op=LS.op;return `<div class="headline"><p>${headline(op)}</p></div>${heroFigs(op)}${gapSplit(op)}${firstMoves(op)}
 <details class="chain-disc" ${window.innerWidth>760?'open':''}><summary>Value chain, October</summary>${chainStrip(op)}</details>
 <h2 class="h2s">Each outcome and the factors that make it</h2>${outcomeCards(op)}
 <div class="grid2">${sec('Factors needing attention',attentionList(op),'Off target, at or near an obligation limit, or newly appeared. Seen at the factor before the books show it.')}<div>${contrastPanel(op)}</div></div>`;}

/* ---------- Act first: the plan under budget and crews, with switches ---------- */
const WHY_FIRST = {'KIS-REPAIR':'Must do: evening supply has no backup','KOB-STOPSOC':'Value: less generator running after dawn; remote change','MTO-INV-CLAIM':`Deadline: warranty notice by ${fdate(siteM('mto').entitlement.notice_deadline)}; the huller depends on it`,'MTO-INV-BUYNOW':`Deadline: the huller’s letter of intent lapses ${fdate(siteM('mto').decision.options.find(x=>x.id==='MTO-HULLER').customer_loi.lapses)}`,'MTO-HULLER':'Value: new paying daytime demand','MTO-BILLING':'Value: restores billed charges; office work','MTO-METER-AUDIT':`Evidence: ${num(siteM('mto').period.actual.unexplained_kwh)} kWh not explained yet`,'BAT-EVIDENCE':`Protects ${usd(OPS.lakeside.t.portfolio.allocation.listed_not_summed['BAT-001_cover_exposure'])} of cover; nothing breaks if it waits a month`,
 'THIKA-EPC-STOPGAP':'Must do: no action fails the batch temperature limit (days with the backup start unproven)','KIRI-REPAIR':'Value: recovers the room’s excess energy','MWEA-AGG':'Value: new customer, conditional on signature','KAS-OEM-STOPGAP':'Must do: no action fails the departures limit (departures missed)','EMB-DEADLINE':'Value: lower charging bill under the November tariff','RUI-ABSORB6':'Contract decision for the city'};
const VW=(id,w,extra='')=>{const n=DOPT(id)?.crew_visits??0;return `${num(n)} ${w}${n===1?'':'s'}${extra}`;};
const VISIT = {'KIS-REPAIR':[()=>VW('KIS-REPAIR','crew visit'),'field'],'MTO-INV-CLAIM':[()=>VW('MTO-INV-CLAIM','crew visit',' (meter check on the same visit)'),'field'],'MTO-INV-BUYNOW':[()=>VW('MTO-INV-BUYNOW','crew visit',' (meter check on the same visit)'),'field'],'BAT-EVIDENCE':[()=>VW('BAT-EVIDENCE','crew visit'),'field'],'KOB-STOPSOC':[()=>'Remote: vendor change + supervised trial','remote'],'MTO-HULLER':[()=>`Connection contractor (in the ${usd(DOPT('MTO-HULLER').net_one_off)})`,'contractor'],'MTO-BILLING':[()=>'Office: billing records','remote'],'MTO-METER-AUDIT':[()=>'On the inverter visit','field'],
 'THIKA-EPC-STOPGAP':[()=>'Site staff: night rota + SMS alarm','remote'],'KIRI-REPAIR':[()=>VW('KIRI-REPAIR','technician visit'),'field'],'MWEA-AGG':[()=>VW('MWEA-AGG','technician visit',' (ethylene curtain)'),'field'],'KAS-OEM-STOPGAP':[()=>'Operations: one bus to Ruiru each night','remote'],'EMB-DEADLINE':[()=>'Remote: charger management schedule','remote'],'RUI-ABSORB6':[()=>'Contract: no technician work','remote']};
/* a restore path's 12-month result is the option's value against the reference: its one-off plus its money effect to the restore
   (extra fuel, under Optimize); never a one-off cost */
const restoreValue=id=>{const d=DOPT(id);return [usd(d.value,true),`the option’s value against the reference: ${usd(d.net_one_off)} one-off and ${usd(-d.monthly_or_horizon_change)} of extra fuel to the restore; counted in the plan’s 12-month change`];};
const PLAN_EFFECT={'MTO-INV-CLAIM':()=>restoreValue('MTO-INV-CLAIM'),'MTO-INV-BUYNOW':()=>restoreValue('MTO-INV-BUYNOW'),'BAT-EVIDENCE':()=>[`Protects ${usd(OPS.lakeside.t.portfolio.allocation.listed_not_summed['BAT-001_cover_exposure'])} of cover`,'at stake, not money; no saving claimed']};
const harvestValue=()=>derivedPlan('harvest').value;
